window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-abbcb2f314e57f86"]={"versions": [{"id": "FIG-abbcb2f314e57f86", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2 UML-Klassendiagramm) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (Release R22-11).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Domäne <code>ApplicationDesign::PortInterface::StateManagement</code>.\n</li><li><strong>Technischer Zweck:</strong> Formale Modellierung zweier komplementärer Notifikationspfade für Zustandswechsel im Adaptive State Management (SM):\n<ol class=\"fig-list\"><li><em>Plattform-Zustandswechsel:</em> Signalisierung von Umschaltungen von Funktionsgruppen-Zuständen (<em>Function Group State Switch</em>) an/von der Execution Management (EM) Engine via dedizierter Meta-Klasse.\n</li><li><em>Applikations-/Dienst-interne Zustandswechsel:</em> Signalisierung interner Zustandsübergänge an andere Adaptive Applications über generische ara::com-Dienstschnittstellen (<code>ServiceInterface</code>) via <code>Field</code>-Notifikation (<code>hasNotifier</code>).\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code></strong> (Abstrakte Basisklasse)\n<ul class=\"fig-list\"><li>Stereotypen/Attribute: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>.\n</li><li>Zentrales Wurzelelement für typisierte Schnittstellendefinitionen an <code>PortPrototype</code>-Instanzen.\n</li></ul>\n</li><li><strong><code>StateManagementPortInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>PortInterface</code>.\n</li><li>Abstrakter Anker für SM-spezifische Kommunikations-Ports.\n</li></ul>\n</li><li><strong><code>StateManagementNotificationInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>StateManagementPortInterface</code>.\n</li><li>Basisklasse für ereignis- bzw. zustandsgetriebene SM-Benachrichtigungen.\n</li></ul>\n</li><li><strong><code>StateManagementFunctionGroupSwitchNotificationInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>StateManagementNotificationInterface</code>.\n</li><li>Dient der Typisierung von Ports, die SM-seitig über Statusänderungen von Funktionsgruppen informieren.\n</li><li>Hat gerichtete Assoziation <code>+modeGroup</code> mit Multiplizität <code>[0..1]</code> auf <code>ModeDeclarationGroup</code>.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroup</code></strong>\n<ul class=\"fig-list\"><li>Stereotypen/Attribute: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>.\n</li><li>Definiert den formalen Wertebereich (Modes) der zu überwachenden bzw. zu schaltenden Funktionsgruppe.\n</li></ul>\n</li><li><strong><code>ServiceInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>PortInterface</code>.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ majorVersion: PositiveInteger [0..1]</code>\n</li><li><code>+ minorVersion: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li>Aggregiert via Komposition (<code>black diamond</code>) zero-to-many <code>Field</code>-Instanzen (<code>+field 0..*</code>).\n</li><li>Assoziations-Stereotyp: <code>«atpVariation, atpSplitable»</code> (ermöglicht variantenabhängige Bindung und ARXML-File-Splitting).\n</li></ul>\n</li><li><strong><code>Field</code></strong> (Spezialisierung von <code>AutosarDataPrototype</code>)\n<ul class=\"fig-list\"><li>Modelliert Datenfelder innerhalb serviceorientierter Schnittstellen.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ hasGetter: Boolean [0..1]</code>\n</li><li><code>+ hasNotifier: Boolean [0..1]</code>\n</li><li><code>+ hasSetter: Boolean [0..1]</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Struktur zweier distinkter Laufzeitpfade:</p>\n<ol class=\"fig-list\"><li><strong>Function Group Switch Notification (Plattformebene / EM-Kopplung):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Ein Zustandswechsel einer Funktionsgruppe wird angefordert oder von Execution Management (EM) vollzogen.\n</li><li><strong>Ablauf:</strong> State Management empfängt oder publiziert den Übergang über einen Port, der durch <code>StateManagementFunctionGroupSwitchNotificationInterface</code> typisiert ist.\n</li><li><strong>Typbindung:</strong> Die übermittelten Werte sind strikt auf die in der referenzierten <code>ModeDeclarationGroup</code> definierten Modus-Literale beschränkt.\n</li><li><strong>Pfad:</strong> Interne Plattform-Interaktion (IPC/Plattform-Interface zwischen SM und EM/Plattform-Diensten), synchron oder asynchron entkoppelt je nach EM-Zustandsmaschinen-Implementierung.\n</li></ul>\n</li><li><strong>Internal State Switch Notification (Applikationsebene / Service-Orientierung):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Interner Zustandswechsel innerhalb einer Applikation oder des State Managements (z. B. Betriebsmodus, Fehlermodus).\n</li><li><strong>Ablauf:</strong> Auslösung über ara::com Event-/Notifier-Mechanismus (<code>Field.hasNotifier == true</code>).\n</li><li><strong>Synchronisation:</strong> Asynchrone Publish-Subscribe-Verteilung an alle abonnierenden Komponenten (<code>Skeleton</code> sendet Notifier, <code>Proxy</code> empfängt über Event-Subscription-Callback/Future).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest- &amp; Port-Konfiguration (ARXML):</strong>\n<ul class=\"fig-list\"><li>Für Standard-Funktionsgruppen-Notifikationen (SM ↔ EM) darf kein Standard-<code>ServiceInterface</code> zweckentfremdet werden; zwingend ist <code>StateManagementFunctionGroupSwitchNotificationInterface</code> zu instanziieren und die zugehörige <code>ModeDeclarationGroup</code> eindeutig zuzuordnen (<code>0..1</code>).\n</li><li>Wenn ein Function Group State über Service-Grenzen hinweg an Standard-Applikationen propagiert werden soll, muss dieser im Service-Manifest über ein <code>ServiceInterface</code> mit einem <code>Field</code> abgebildet werden, bei dem <code>hasNotifier = true</code> gesetzt ist.\n</li></ul>\n</li><li><strong>Codegenerator- &amp; API-Auswirkung (ara::com / ara::sm):</strong>\n<ul class=\"fig-list\"><li>Aus <code>StateManagementFunctionGroupSwitchNotificationInterface</code> generiert der Adaptive-Generator plattformspezifische SM/EM-Bindings (zustandsorientierte Typen basierend auf der Modusdeklaration).\n</li><li>Aus <code>ServiceInterface.field</code> generiert der ara::com-Generator standardisierte Skeleton-/Proxy-Klassen mit <code>field::RegisterGetHandler()</code>, <code>field::Update()</code> (Notifier) bzw. <code>field::SetHandler()</code>.\n</li></ul>\n</li><li><strong>Restriktionen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li><code>«atpSplitable»</code> an <code>ServiceInterface.field</code>: Entwickler können Felder über mehrere ARXML-Dateien/Teilpakete verteilen; der Linker/Manifest-Compiler aggregiert diese zur vollständigen Schnittstelle.\n</li><li>Fehlt die Referenz <code>+modeGroup</code> an <code>StateManagementFunctionGroupSwitchNotificationInterface</code>, ist das Manifest unvollständig, da der Zielzustandsraum für die Validierung im Generator undefiniert bleibt.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2b1d5cfcdcef9e33", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2 UML-Klassendiagramm) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (Release R22-11).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Domäne <code>ApplicationDesign::PortInterface::StateManagement</code>.\n</li><li><strong>Technischer Zweck:</strong> Formale Modellierung zweier komplementärer Notifikationspfade für Zustandswechsel im Adaptive State Management (SM):\n<ol class=\"fig-list\"><li><em>Plattform-Zustandswechsel:</em> Signalisierung von Umschaltungen von Funktionsgruppen-Zuständen (<em>Function Group State Switch</em>) an/von der Execution Management (EM) Engine via dedizierter Meta-Klasse.\n</li><li><em>Applikations-/Dienst-interne Zustandswechsel:</em> Signalisierung interner Zustandsübergänge an andere Adaptive Applications über generische ara::com-Dienstschnittstellen (<code>ServiceInterface</code>) via <code>Field</code>-Notifikation (<code>hasNotifier</code>).\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code></strong> (Abstrakte Basisklasse)\n<ul class=\"fig-list\"><li>Stereotypen/Attribute: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>.\n</li><li>Zentrales Wurzelelement für typisierte Schnittstellendefinitionen an <code>PortPrototype</code>-Instanzen.\n</li></ul>\n</li><li><strong><code>StateManagementPortInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>PortInterface</code>.\n</li><li>Abstrakter Anker für SM-spezifische Kommunikations-Ports.\n</li></ul>\n</li><li><strong><code>StateManagementNotificationInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>StateManagementPortInterface</code>.\n</li><li>Basisklasse für ereignis- bzw. zustandsgetriebene SM-Benachrichtigungen.\n</li></ul>\n</li><li><strong><code>StateManagementFunctionGroupSwitchNotificationInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>StateManagementNotificationInterface</code>.\n</li><li>Dient der Typisierung von Ports, die SM-seitig über Statusänderungen von Funktionsgruppen informieren.\n</li><li>Hat gerichtete Assoziation <code>+modeGroup</code> mit Multiplizität <code>[0..1]</code> auf <code>ModeDeclarationGroup</code>.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroup</code></strong>\n<ul class=\"fig-list\"><li>Stereotypen/Attribute: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>, <code>UploadableDesignElement</code>.\n</li><li>Definiert den formalen Wertebereich (Modes) der zu überwachenden bzw. zu schaltenden Funktionsgruppe.\n</li></ul>\n</li><li><strong><code>ServiceInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>PortInterface</code>.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ majorVersion: PositiveInteger [0..1]</code>\n</li><li><code>+ minorVersion: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li>Aggregiert via Komposition (<code>black diamond</code>) zero-to-many <code>Field</code>-Instanzen (<code>+field 0..*</code>).\n</li><li>Assoziations-Stereotyp: <code>«atpVariation, atpSplitable»</code> (ermöglicht variantenabhängige Bindung und ARXML-File-Splitting).\n</li></ul>\n</li><li><strong><code>Field</code></strong> (Spezialisierung von <code>AutosarDataPrototype</code>)\n<ul class=\"fig-list\"><li>Modelliert Datenfelder innerhalb serviceorientierter Schnittstellen.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ hasGetter: Boolean [0..1]</code>\n</li><li><code>+ hasNotifier: Boolean [0..1]</code>\n</li><li><code>+ hasSetter: Boolean [0..1]</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Struktur zweier distinkter Laufzeitpfade:</p>\n<ol class=\"fig-list\"><li><strong>Function Group Switch Notification (Plattformebene / EM-Kopplung):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Ein Zustandswechsel einer Funktionsgruppe wird angefordert oder von Execution Management (EM) vollzogen.\n</li><li><strong>Ablauf:</strong> State Management empfängt oder publiziert den Übergang über einen Port, der durch <code>StateManagementFunctionGroupSwitchNotificationInterface</code> typisiert ist.\n</li><li><strong>Typbindung:</strong> Die übermittelten Werte sind strikt auf die in der referenzierten <code>ModeDeclarationGroup</code> definierten Modus-Literale beschränkt.\n</li><li><strong>Pfad:</strong> Interne Plattform-Interaktion (IPC/Plattform-Interface zwischen SM und EM/Plattform-Diensten), synchron oder asynchron entkoppelt je nach EM-Zustandsmaschinen-Implementierung.\n</li></ul>\n</li><li><strong>Internal State Switch Notification (Applikationsebene / Service-Orientierung):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Interner Zustandswechsel innerhalb einer Applikation oder des State Managements (z. B. Betriebsmodus, Fehlermodus).\n</li><li><strong>Ablauf:</strong> Auslösung über ara::com Event-/Notifier-Mechanismus (<code>Field.hasNotifier == true</code>).\n</li><li><strong>Synchronisation:</strong> Asynchrone Publish-Subscribe-Verteilung an alle abonnierenden Komponenten (<code>Skeleton</code> sendet Notifier, <code>Proxy</code> empfängt über Event-Subscription-Callback/Future).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Typisierung:</strong> Ports für Benachrichtigungen über Zustandswechsel von Funktionsgruppen müssen mit <code>StateManagementFunctionGroupSwitchNotificationInterface</code> typisiert werden.\n</li><li><strong>Modus-Deklaration &amp; Upload-Fähigkeit:</strong> Die referenzierte <code>ModeDeclarationGroup</code> (<code>+modeGroup [0..1]</code>) definiert verbindlich die zulässigen Zustände der Funktionsgruppe. Durch die Spezialisierung als <code>UploadableDesignElement</code> kann sie als modulares, eigenständig aktualisierbares Entwurfselement in Update-Paketen bereitgestellt werden.\n</li><li><strong>Service-orientierte Zustandsübertragung:</strong> Interne Zustände werden über <code>Field</code>-Elemente innerhalb von <code>ServiceInterface</code> abgebildet. Für Notifikationen muss <code>hasNotifier</code> zwingend auf <code>true</code> gesetzt sein; <code>hasGetter</code> und <code>hasSetter</code> sind je nach Zugriffsanforderung optional konfigurierbar.\n</li><li><strong>Modellierungs-Flexibilität:</strong> Die Komposition <code>+field</code> ist mit <code>«atpVariation, atpSplitable»</code> versehen, was ein Aufteilen über mehrere ARXML-Dateien sowie eine variantenabhängige Konfiguration ermöglicht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-904e1b76dd55be60", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2 UML-Klassendiagramm) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (Release R22-11).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Domäne <code>ApplicationDesign::PortInterface::StateManagement</code>.\n</li><li><strong>Technischer Zweck:</strong> Formale Modellierung zweier komplementärer Notifikationspfade für Zustandswechsel im Adaptive State Management (SM):\n<ol class=\"fig-list\"><li><em>Plattform-Zustandswechsel:</em> Signalisierung von Umschaltungen von Funktionsgruppen-Zuständen (<em>Function Group State Switch</em>) an/von der Execution Management (EM) Engine via dedizierter Meta-Klasse.\n</li><li><em>Applikations-/Dienst-interne Zustandswechsel:</em> Signalisierung interner Zustandsübergänge an andere Adaptive Applications über generische ara::com-Dienstschnittstellen (<code>ServiceInterface</code>) via <code>Field</code>-Notifikation (<code>hasNotifier</code>).\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code></strong> (Abstrakte Basisklasse)\n<ul class=\"fig-list\"><li>Stereotypen/Attribute: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>.\n</li><li>Zentrales Wurzelelement für typisierte Schnittstellendefinitionen an <code>PortPrototype</code>-Instanzen.\n</li></ul>\n</li><li><strong><code>StateManagementPortInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>PortInterface</code>.\n</li><li>Abstrakter Anker für SM-spezifische Kommunikations-Ports.\n</li></ul>\n</li><li><strong><code>StateManagementNotificationInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>StateManagementPortInterface</code>.\n</li><li>Basisklasse für ereignis- bzw. zustandsgetriebene SM-Benachrichtigungen.\n</li></ul>\n</li><li><strong><code>StateManagementFunctionGroupSwitchNotificationInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>StateManagementNotificationInterface</code>.\n</li><li>Dient der Typisierung von Ports, die SM-seitig über Statusänderungen von Funktionsgruppen informieren.\n</li><li>Hat gerichtete Assoziation <code>+modeGroup</code> mit Multiplizität <code>[0..1]</code> auf <code>ModeDeclarationGroup</code>.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroup</code></strong>\n<ul class=\"fig-list\"><li>Stereotypen/Attribute: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>, <code>UploadableDesignElement</code>.\n</li><li>Definiert den formalen Wertebereich (Modes) der zu überwachenden bzw. zu schaltenden Funktionsgruppe.\n</li></ul>\n</li><li><strong><code>ServiceInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>PortInterface</code>.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ majorVersion: PositiveInteger [0..1]</code>\n</li><li><code>+ minorVersion: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li>Aggregiert via Komposition (<code>black diamond</code>) zero-to-many <code>Field</code>-Instanzen (<code>+field 0..*</code>).\n</li><li>Assoziations-Stereotyp: <code>«atpVariation, atpSplitable»</code> (ermöglicht variantenabhängige Bindung und ARXML-File-Splitting).\n</li></ul>\n</li><li><strong><code>Field</code></strong> (Spezialisierung von <code>AutosarDataPrototype</code>)\n<ul class=\"fig-list\"><li>Modelliert Datenfelder innerhalb serviceorientierter Schnittstellen.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ hasGetter: Boolean [0..1]</code>\n</li><li><code>+ hasNotifier: Boolean [0..1]</code>\n</li><li><code>+ hasSetter: Boolean [0..1]</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Struktur zweier distinkter Laufzeitpfade:</p>\n<ol class=\"fig-list\"><li><strong>Function Group Switch Notification (Plattformebene / EM-Kopplung):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Ein Zustandswechsel einer Funktionsgruppe wird angefordert oder von Execution Management (EM) vollzogen.\n</li><li><strong>Ablauf:</strong> State Management empfängt oder publiziert den Übergang über einen Port, der durch <code>StateManagementFunctionGroupSwitchNotificationInterface</code> typisiert ist.\n</li><li><strong>Typbindung:</strong> Die übermittelten Werte sind strikt auf die in der referenzierten <code>ModeDeclarationGroup</code> definierten Modus-Literale beschränkt.\n</li><li><strong>Pfad:</strong> Interne Plattform-Interaktion (IPC/Plattform-Interface zwischen SM und EM/Plattform-Diensten), synchron oder asynchron entkoppelt je nach EM-Zustandsmaschinen-Implementierung.\n</li></ul>\n</li><li><strong>Internal State Switch Notification (Applikationsebene / Service-Orientierung):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Interner Zustandswechsel innerhalb einer Applikation oder des State Managements (z. B. Betriebsmodus, Fehlermodus).\n</li><li><strong>Ablauf:</strong> Auslösung über ara::com Event-/Notifier-Mechanismus (<code>Field.hasNotifier == true</code>).\n</li><li><strong>Synchronisation:</strong> Asynchrone Publish-Subscribe-Verteilung an alle abonnierenden Komponenten (<code>Skeleton</code> sendet Notifier, <code>Proxy</code> empfängt über Event-Subscription-Callback/Future).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Typisierung:</strong> Ports für Benachrichtigungen über Zustandswechsel von Funktionsgruppen müssen mit <code>StateManagementFunctionGroupSwitchNotificationInterface</code> typisiert werden.\n</li><li><strong>Modus-Deklaration &amp; Upload-Fähigkeit:</strong> Die referenzierte <code>ModeDeclarationGroup</code> (<code>+modeGroup [0..1]</code>) definiert verbindlich die zulässigen Zustände der Funktionsgruppe. Durch die Spezialisierung als <code>UploadableDesignElement</code> kann sie als modulares, eigenständig aktualisierbares Entwurfselement in Update-Paketen bereitgestellt werden.\n</li><li><strong>Service-orientierte Zustandsübertragung:</strong> Interne Zustände werden über <code>Field</code>-Elemente innerhalb von <code>ServiceInterface</code> abgebildet. Für Notifikationen muss <code>hasNotifier</code> zwingend auf <code>true</code> gesetzt sein; <code>hasGetter</code> und <code>hasSetter</code> sind je nach Zugriffsanforderung optional konfigurierbar.\n</li><li><strong>Modellierungs-Flexibilität:</strong> Die Komposition <code>+field</code> ist mit <code>«atpVariation, atpSplitable»</code> versehen, was ein Aufteilen über mehrere ARXML-Dateien sowie eine variantenabhängige Konfiguration ermöglicht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a1b6d31dc060ca3a", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2 UML-Klassendiagramm) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (Release R22-11).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Domäne <code>ApplicationDesign::PortInterface::StateManagement</code>.\n</li><li><strong>Technischer Zweck:</strong> Formale Modellierung zweier komplementärer Notifikationspfade für Zustandswechsel im Adaptive State Management (SM):\n<ol class=\"fig-list\"><li><em>Plattform-Zustandswechsel:</em> Signalisierung von Umschaltungen von Funktionsgruppen-Zuständen (<em>Function Group State Switch</em>) an/von der Execution Management (EM) Engine via dedizierter Meta-Klasse.\n</li><li><em>Applikations-/Dienst-interne Zustandswechsel:</em> Signalisierung interner Zustandsübergänge an andere Adaptive Applications über generische ara::com-Dienstschnittstellen (<code>ServiceInterface</code>) via <code>Field</code>-Notifikation (<code>hasNotifier</code>).\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code></strong> (Abstrakte Basisklasse)\n<ul class=\"fig-list\"><li>Stereotypen/Attribute: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>.\n</li><li>Zentrales Wurzelelement für typisierte Schnittstellendefinitionen an <code>PortPrototype</code>-Instanzen.\n</li></ul>\n</li><li><strong><code>StateManagementPortInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>PortInterface</code>.\n</li><li>Abstrakter Anker für SM-spezifische Kommunikations-Ports.\n</li></ul>\n</li><li><strong><code>StateManagementNotificationInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>StateManagementPortInterface</code>.\n</li><li>Basisklasse für ereignis- bzw. zustandsgetriebene SM-Benachrichtigungen.\n</li></ul>\n</li><li><strong><code>StateManagementFunctionGroupSwitchNotificationInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>StateManagementNotificationInterface</code>.\n</li><li>Dient der Typisierung von Ports, die SM-seitig über Statusänderungen von Funktionsgruppen informieren.\n</li><li>Hat gerichtete Assoziation <code>+modeGroup</code> mit Multiplizität <code>[0..1]</code> auf <code>ModeDeclarationGroup</code>.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroup</code></strong>\n<ul class=\"fig-list\"><li>Stereotypen/Attribute: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>, <code>UploadableDesignElement</code>.\n</li><li>Definiert den formalen Wertebereich (Modes) der zu überwachenden bzw. zu schaltenden Funktionsgruppe.\n</li></ul>\n</li><li><strong><code>ServiceInterface</code></strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>PortInterface</code>.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ majorVersion: PositiveInteger [0..1]</code>\n</li><li><code>+ minorVersion: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li>Aggregiert via Komposition (<code>black diamond</code>) zero-to-many <code>Field</code>-Instanzen (<code>+field 0..*</code>).\n</li><li>Assoziations-Stereotyp: <code>«atpVariation, atpSplitable»</code> (ermöglicht variantenabhängige Bindung und ARXML-File-Splitting).\n</li></ul>\n</li><li><strong><code>Field</code></strong> (Spezialisierung von <code>AutosarDataPrototype</code>)\n<ul class=\"fig-list\"><li>Modelliert Datenfelder innerhalb serviceorientierter Schnittstellen.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ hasGetter: Boolean [0..1]</code>\n</li><li><code>+ hasNotifier: Boolean [0..1]</code>\n</li><li><code>+ hasSetter: Boolean [0..1]</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Struktur zweier distinkter Laufzeitpfade:</p>\n<ol class=\"fig-list\"><li><strong>Function Group Switch Notification (Plattformebene / EM-Kopplung):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Ein Zustandswechsel einer Funktionsgruppe wird angefordert oder von Execution Management (EM) vollzogen.\n</li><li><strong>Ablauf:</strong> State Management empfängt oder publiziert den Übergang über einen Port, der durch <code>StateManagementFunctionGroupSwitchNotificationInterface</code> typisiert ist.\n</li><li><strong>Typbindung:</strong> Die übermittelten Werte sind strikt auf die in der referenzierten <code>ModeDeclarationGroup</code> definierten Modus-Literale beschränkt.\n</li><li><strong>Pfad:</strong> Interne Plattform-Interaktion (IPC/Plattform-Interface zwischen SM und EM/Plattform-Diensten), synchron oder asynchron entkoppelt je nach EM-Zustandsmaschinen-Implementierung.\n</li></ul>\n</li><li><strong>Internal State Switch Notification (Applikationsebene / Service-Orientierung):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Interner Zustandswechsel innerhalb einer Applikation oder des State Managements (z. B. Betriebsmodus, Fehlermodus).\n</li><li><strong>Ablauf:</strong> Auslösung über ara::com Event-/Notifier-Mechanismus (<code>Field.hasNotifier == true</code>).\n</li><li><strong>Synchronisation:</strong> Asynchrone Publish-Subscribe-Verteilung an alle abonnierenden Komponenten (<code>Skeleton</code> sendet Notifier, <code>Proxy</code> empfängt über Event-Subscription-Callback/Future).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Typisierung:</strong> Ports für Benachrichtigungen über Zustandswechsel von Funktionsgruppen müssen mit <code>StateManagementFunctionGroupSwitchNotificationInterface</code> typisiert werden.\n</li><li><strong>Modus-Deklaration &amp; Upload-Fähigkeit:</strong> Die referenzierte <code>ModeDeclarationGroup</code> (<code>+modeGroup [0..1]</code>) definiert verbindlich die zulässigen Zustände der Funktionsgruppe. Durch die Spezialisierung als <code>UploadableDesignElement</code> kann sie als modulares, eigenständig aktualisierbares Entwurfselement in Update-Paketen bereitgestellt werden.\n</li><li><strong>Service-orientierte Zustandsübertragung:</strong> Interne Zustände werden über <code>Field</code>-Elemente innerhalb von <code>ServiceInterface</code> abgebildet. Für Notifikationen muss <code>hasNotifier</code> zwingend auf <code>true</code> gesetzt sein; <code>hasGetter</code> und <code>hasSetter</code> sind je nach Zugriffsanforderung optional konfigurierbar.\n</li><li><strong>Modellierungs-Flexibilität:</strong> Die Komposition <code>+field</code> ist mit <code>«atpVariation, atpSplitable»</code> versehen, was ein Aufteilen über mehrere ARXML-Dateien sowie eine variantenabhängige Konfiguration ermöglicht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-abbcb2f314e57f86", "to": "FIG-2b1d5cfcdcef9e33", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>ModeDeclarationGroup</code>:</strong> Erweiterung um die Metaklasse bzw. den Stereotyp <code>UploadableDesignElement</code> (normativ).\n</li><li><strong>Diagramm-Layout:</strong> <code>ServiceInterface</code> wurde von unterhalb von <code>PortInterface</code> rechts daneben platziert (Generalisierungspfeil weist horizontal nach links); <code>ModeDeclarationGroup</code> wurde aus der linken unteren Ecke in die untere Mitte verschoben, wodurch der Assoziationspfeil <code>+modeGroup [0..1]</code> von <code>StateManagementFunctionGroupSwitchNotificationInterface</code> nun horizontal nach rechts verläuft (redaktionell).\n</li></ul>"}, {"from": "FIG-2b1d5cfcdcef9e33", "to": "FIG-904e1b76dd55be60", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-904e1b76dd55be60", "to": "FIG-a1b6d31dc060ca3a", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
